#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic)
# count_events_offline.sh <run-root>... — for every FISH session under the given
# roots whose fishlog/discards.txt says total_events=deferred (FISH_EVENT_COUNT=0
# campaigns), count the CTF events with babeltrace2 into <run>/events_count.txt.
# Discards are already exact (from `lttng stop`); this only fills the total.
for root in "$@"; do
  find "$root" -type f -path "*/fishlog/discards.txt" 2>/dev/null | while read -r f; do
    grep -q "total_events=deferred" "$f" || continue
    sdir=$(dirname "$(dirname "$f")"); trace=$(find "$sdir/ros2" -name metadata -printf '%h\n' 2>/dev/null | head -1)
    [ -n "$trace" ] || { echo "$sdir: no trace"; continue; }
    run=$(dirname "$sdir"); out="$run/events_count.txt"      # session dirs are root-owned (container); the run dir is ours
    [ -s "$out" ] && { echo "$run: $(cat "$out") (cached)"; continue; }
    n=$(babeltrace2 "$trace" 2>/dev/null | wc -l)
    echo "total_events=$n" > "$out" && echo "$run: total_events=$n"
  done
done
